      // Guide
      guide: {
        title: "রিটেইলার মার্কিং গাইড",
        overview:
          "রিটেইলার মার্কিং-এর মাধ্যমে আপনি গ্লোবাল মার্কিং (যেমন DRC, RSP, BSP) তৈরি করে সব হাউসের রিটেইলারদের উপর অ্যাসাইন করতে পারেন। মার্কিং রিপোর্ট বর্জন ফিল্টার এবং লাইভ অ্যাক্টিভেশন সেকশনে ব্যবহৃত হয়।",
        features_title: "পেজ ও অপশন",
        steps_title: "সাধারণ কাজের ধারা",
        notes_title: "গুরুত্বপূর্ণ নোট",
        features: {
          f1: { title: "মার্কিং", desc: "গ্লোবাল মার্কিং তৈরি, নাম পরিবর্তন বা মুছে ফেলুন। কোনো রিটেইলার অ্যাসাইন থাকলে নিষ্ক্রিয় করা যাবে না।" },
          f2: { title: "মার্ক করা রিটেইলার", desc: "হাউস অনুযায়ী রিটেইলার দেখুন এবং প্রতিটির মার্কিং দেখুন। একক মার্কিং দেখতে ফিল্টার ব্যবহার করুন।" },
          f3: { title: "মার্কিং অ্যাসাইন", desc: "মার্কিং বেছে নিন, রিটেইলার খুঁজুন, তারপর বাল্কে অ্যাসাইন করুন। বাম পাশে ইতিমধ্যে মার্ক করা রিটেইলার দেখানো হয়।" },
          f4: { title: "মার্কিং ইম্পোর্ট", desc: "Retailer Number এবং Marking কলামসহ এক্সেল ফাইল আপলোড করুন। নিশ্চিত করার আগে সারি ও নতুন মার্কিং প্রিভিউ দেখুন।" },
          f5: { title: "মার্কিং ইতিহাস", desc: "সময়, কর্মী ও মন্তব্যসহ প্রতিটি অ্যাসাইন/রিমুভ কর্মের অডিট ট্রেইল।" },
          f6: { title: "এক্সপোর্ট", desc: "নির্বাচিত হাউস ও মার্কিং অনুযায়ী বর্তমান অ্যাসাইনমেন্ট তালিকা এক্সেল ফাইল হিসেবে ডাউনলোড করুন।" },
        },
        steps: {
          s1: { title: "মার্কিং তৈরি করুন", desc: "মার্কিং পেজে গিয়ে 'নতুন মার্কিং' চাপুন, নাম ও কোড দিন, তারপর সংরক্ষণ করুন।" },
          s2: { title: "রিটেইলার অ্যাসাইন করুন", desc: "'মার্কিং অ্যাসাইন' খুলুন, মার্কিং বেছে নিন, নাম বা কোড দিয়ে রিটেইলার খুঁজুন, টিক দিন এবং 'Assign to Marking' চাপুন।" },
          s3: { title: "বাল্ক ইম্পোর্ট", desc: "Retailer Number ও Marking কলামসহ এক্সেল ফাইল তৈরি করুন, আপলোড করুন, প্রিভিউ দেখুন, তারপর নিশ্চিত করুন।" },
        },
        notes: {
          n1: { title: "হাউস সীমা", desc: "মার্কিং গ্লোবাল, তবে আপনি শুধু নিজের হাউসের (অথবা অ্যাডমিন হলে সব হাউসের) রিটেইলার দেখতে ও পরিচালনা করতে পারবেন।" },
          n2: { title: "হার্ড ডিলিট", desc: "মার্কিং মুছে ফেললে তা সফট ডিলিট হয়। অডিট ট্রেইল থেকে কিছু স্থায়ীভাবে মুছে যায় না।" },
          n3: { title: "পুনরায় অ্যাসাইন", desc: "মার্কিং সরালে বর্তমান অ্যাসাইনমেন্ট বন্ধ হয়; আবার দিলে নতুন ইতিহাস এন্ট্রি তৈরি হয়।" },
        },
      },
