      guide: {
        title: "কীভাবে ডিপ্লয় করবেন",
        overview: "এই পেজটি সর্বশেষ কমিটেড কোড প্রোডাকশন সার্ভারে ডিপ্লয় করে। এটি একটি আলাদা কন্টেইনারের ভিতরে চলে, তাই ডিপ্লয়ের মাঝখানে পেজ কখনো রিলোড হয় না, এবং পুল থেকে ভেরিফিকেশন পর্যন্ত প্রতিটি ধাপ রিয়েল-টাইমে দেখায়।",
        features_title: "পেজ অপশন",
        steps_title: "সাধারণ ওয়ার্কফ্লো",
        notes_title: "গুরুত্বপূর্ণ নোট",
        features: {
          f1: { title: "সংযোগ অবস্থা", desc: "ডেডিকেটেড ডিপ্লয় সার্ভিস অ্যাক্সেসযোগ্য কিনা দেখায়। শুরু বাটন, প্রগ্রেস, লগ — সবকিছুর জন্য এই কন্টেইনারটি অনলাইন থাকা প্রয়োজন।" },
          f2: { title: "পেন্ডিং কমিট", desc: "গিটহাবে থাকা কিন্তু সার্ভারে এখনো নেই এমন কমিটগুলোর তালিকা, তাদের হ্যাশ এবং তারিখসহ দেখায়। রিমোটের সাথে সিঙ্ক করতে রিফ্রেশ করুন।" },
          f3: { title: "ডিপ্লয় শুরু করুন", desc: "ডিপ্লয় শুরু করে: সর্বশেষ কোড পুল, ডিপেন্ডেন্সি ইনস্টল, ফ্রন্টএন্ড বিল্ড, সার্ভিস রিস্টার্ট, এবং স্বাস্থ্য পরীক্ষা। ডিপ্লয় চললে বাটনটি নিষ্ক্রিয় থাকে।" },
          f4: { title: "ডিপ্লয় সারসংক্ষেপ", desc: "ধাপে ধাপে লাইভ প্রগ্রেস (পুল, ইনস্টল, বিল্ড, রিস্টার্ট, ভেরিফাই) এবং শেষের সফল/ব্যর্থ ফলাফল মোট সময়কালসহ দেখায়।" },
          f5: { title: "লাইভ লগ", desc: "ডিপ্লয়মেন্ট স্ক্রিপ্টের প্রতিটি কমান্ডের কাঁচা আউটপুট দেখানো রিয়েল-টাইম টার্মিনাল।" },
          f6: { title: "রিসেট", desc: "আটকে যাওয়া বা ব্যর্থ ডিপ্লয় অবস্থা পরিষ্কার করে আবার শুরু করতে দেয়। আগের ডিপ্লয় সম্পূর্ণ না হলে শুধু দেখা যায়।" },
        },
        steps: {
          s1: { title: "সর্বশেষ কোড ডিপ্লয় করুন", desc: "১. সংযোগ অবস্থা 'সংযুক্ত' দেখুন। ২. পেন্ডিং কমিট পর্যালোচনা করুন (সবুজ মানে আপ-টু-ডেট)। ৩. 'ডিপ্লয় শুরু করুন' ক্লিক করুন। ৪. সফল ব্যানার দেখা পর্যন্ত ধাপ এবং লাইভ লগ দেখুন।" },
          s2: { title: "ব্যর্থ ডিপ্লয় থেকে পুনরুদ্ধার", desc: "১. কারণের জন্য লাল ত্রুটি ব্যানার এবং লগের শেষ অংশ পড়ুন। ২. অবস্থা পরিষ্কার করতে 'রিসেট' ক্লিক করুন। ৩. সমস্যা ঠিক করুন, কমিট করুন এবং আবার ডিপ্লয় শুরু করুন।" },
        },
        notes: {
          n1: { title: "পেজ বন্ধ করবেন না", desc: "পেজ রিলোড না হলেও, বন্ধ করলে শুধু লাইভ ভিউ থেমে যায় — ডিপ্লয় নিজে কন্টেইনারে চলতে থাকে। পেজ খুলে আবার সংযুক্ত হলে চূড়ান্ত অবস্থা দেখতে পারেন।" },
          n2: { title: "বিল্ড কয়েক মিনিট নেয়", desc: "ফ্রন্টএন্ড প্রোডাকশন বিল্ড (ধাপ ৩) সবচেয়ে দীর্ঘ এবং কয়েক মিনিট লাগতে পারে। প্রগ্রেস পুরো সময় লাইভ থাকে।" },
          n3: { title: "শুধুমাত্র অ্যাডমিন", desc: "ডিপ্লয় সুপার অ্যাডমিন/অ্যাডমিন ইউজারদের মধ্যে সীমাবদ্ধ। সাধারণ ইউজার এই পেজ অ্যাক্সেস করতে পারে না।" },
        },
      },
